package com.finflow.account; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*; @RestController @RequestMapping("/api/v1/accounts") class AccountController{private final AccountRepository r;AccountController(AccountRepository r){this.r=r;} record View(UUID id,String currency,BigDecimal postedBalance,BigDecimal availableBalance,String status,long version){} record Posting(UUID sourceAccountId,UUID destinationAccountId,BigDecimal amount){} @GetMapping("/{id}") View get(@PathVariable UUID id){var a=r.findById(id).orElseThrow();return new View(a.id,a.currency,a.postedBalance,a.availableBalance,a.status,a.version);} @PostMapping("/internal/post") @Transactional Map<String,Object> post(@RequestBody Posting p){var ids=new ArrayList<>(List.of(p.sourceAccountId(),p.destinationAccountId()));ids.sort(Comparator.naturalOrder());var first=r.lockById(ids.get(0)).orElseThrow();var second=r.lockById(ids.get(1)).orElseThrow();var src=first.id.equals(p.sourceAccountId())?first:second;var dst=first.id.equals(p.destinationAccountId())?first:second;src.debit(p.amount());dst.credit(p.amount());return Map.of("status","POSTED");}}